pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 fuzz) public {
        bool shouldPlay = fuzz % 2 == 0;

        address player = address(0x1234);
        vm.deal(player, 100 ether);

        if (shouldPlay) {
            vm.prank(player);
            c.play{value: 10}();
        }

        assertTrue(address(c).balance >= c.pot());
    }
}
